public MediumClaim[] getMediumClaimByClaimCriteriaNew(ClaimCriteria claimCriteria, int iOffset, int iCount, int iClinicID) {
	String sQry = "select mc from MediumClaim mc,VisitDetails vd where mc.C_ID = "+iClinicID;

	if(claimCriteria.getBtStatusGroup() != null && claimCriteria.getBtStatusGroup()[0] == Claim_ClaimStatus.CLARIFICATIONOPENED.getClaim_ClaimStatus()) {
		sQry = "select mc,cm.sDescription FROM MediumClaim mc,VisitDetails vd,Task T,ClinicMaster cm";
	}

	if(claimCriteria.getiPatient_Id() != 0) {
		sQry = sQry + " and mc.P_ID = "+claimCriteria.getiPatient_Id();
	}

	if(claimCriteria.getiProvider_Id() != 0) {
		sQry = sQry + " and vd.iPhysicianId = "+claimCriteria.getiProvider_Id();
	}

	if(claimCriteria.getBtTimelyFilingLimit() == Enums.TimilyFilingLimit.Thirty.getTimilyFilingLimit()) {
		sQry = sQry+" and mc.STATUS in(1,2,4,5,6,12,13)";
	}

	if(claimCriteria.getBtClaimHold() == Enums.HoldClaimSearchCriteria.GeneralHoldExclude.getHoldClaimSearchCriteria()) {
		sQry = sQry + " and mc.btClaimHold in(" + Enums.HoldClaimStatus.UnHolded.getHoldClaimStatus() +")";
	}

	if(claimCriteria.getsOrderByFields() != null) {
		sQry = sQry + " order by mc.DOS desc";
	}

	Query HQRY = session.createQuery(sQry);
	HQRY.setFirstResult(iOffset);
	HQRY.setMaxResults(iCount);
	return HQRY.list();
}

